/**
 * script.js — Landing Page Attribution Bridge
 * ============================================
 *
 * PART OF:  Telegram Classroom Product v1.0
 * FIX #:    12
 *
 * Reads configuration from config.js (loaded before this file).
 * If config.js is missing or a value is blank, uses safe fallbacks.
 *
 * DO NOT EDIT THIS FILE — edit config.js instead.
 */

(function () {
  'use strict';

  // ==========================================
  // 0. READ CONFIG (with fallbacks)
  // ==========================================

  const CFG = window.CLASSROOM_CONFIG || {};

  const ATTRIBUTION_ENDPOINT =
    String(CFG.attributionEndpoint || "").trim() ||
    "https://script.google.com/macros/s/AKfycbynVX4I8qKxsC_hj9Irb8I9izbcnq4yAHjg3taj3PmXJ8ECFkT3XYq8uo3GmyW5Qt7P/exec";

  const TELEGRAM_BOT_HANDLE =
    String(CFG.telegramBotHandle || "").trim().replace(/^@/, "") ||
    "AIA_CSbot";

  const TELEGRAM_BASE =
    "https://t.me/" + TELEGRAM_BOT_HANDLE + "?start=facebook_guide_";

  const META_PIXEL_ID =
    String(CFG.metaPixelId || "").trim();

  // ==========================================
  // 1. SAVE SELAR PARAMS BEFORE CLEANING URL
  // ==========================================

  const landingParams = new URLSearchParams(window.location.search);

  const selarFullName = landingParams.get('fullname') || '';
  const selarEmail    = landingParams.get('email')    || '';
  const landingFbclid = landingParams.get('fbclid')   || '';

  // Preserve an existing Facebook click cookie.
  const existingFbc = document.cookie
    .split(';')
    .some(function (cookie) {
      return cookie.trim().startsWith('_fbc=');
    });

  // Create fbc only from a genuine fbclid parameter.
  if (landingFbclid && !existingFbc) {
    const fbcValue = 'fb.1.' + Date.now() + '.' + landingFbclid;
    document.cookie =
      '_fbc=' + encodeURIComponent(fbcValue) +
      '; Path=/; Max-Age=7776000; SameSite=Lax; Secure';
  }

  // Remove personal information before Meta PageView fires.
  if (
    landingParams.has('fullname') ||
    landingParams.has('email') ||
    landingParams.has('fbclid')
  ) {
    const cleanUrl = new URL(window.location.href);
    cleanUrl.searchParams.delete('fullname');
    cleanUrl.searchParams.delete('email');
    cleanUrl.searchParams.delete('fbclid');
    window.history.replaceState(
      {},
      document.title,
      cleanUrl.pathname + cleanUrl.search + cleanUrl.hash
    );
  }

  // ==========================================
  // 2. META PIXEL (only if configured)
  // ==========================================

  if (META_PIXEL_ID) {
    !function(f,b,e,v,n,t,s)
    {if(f.fbq)return;n=f.fbq=function(){n.callMethod?
    n.callMethod.apply(n,arguments):n.queue.push(arguments)};
    if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';
    n.queue=[];t=b.createElement(e);t.async=!0;t.src=v;
    s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}
    (window, document,'script','https://connect.facebook.net/en_US/fbevents.js');

    window.fbq('init', META_PIXEL_ID);
    window.fbq('track', 'PageView');
  } else {
    console.log('Meta Pixel ID not configured — skipping pixel tracking.');
  }

  // ==========================================
  // 3. ATTRIBUTION BRIDGE CONTROL
  // ==========================================

  const ATTRIBUTION_BRIDGE_ENABLED =
    Boolean(ATTRIBUTION_ENDPOINT && TELEGRAM_BOT_HANDLE);

  if (!ATTRIBUTION_BRIDGE_ENABLED) {
    console.warn(
      'Attribution bridge disabled: missing attributionEndpoint or telegramBotHandle in config.js'
    );
    return;
  }

  // ==========================================
  // 4. FIND TELEGRAM BUTTON
  // ==========================================

  const telegramButton = document.querySelector(
    'a.btn-tg[href*="t.me/"]'
  );

  if (!telegramButton) {
    console.error('Telegram button not found on page.');
    return;
  }

  const originalHref = telegramButton.href;
  const originalText = telegramButton.textContent;

  let attributionReady = false;

  telegramButton.addEventListener('click', function (event) {
    if (!attributionReady) {
      event.preventDefault();
      telegramButton.textContent = 'Preparing your secure Telegram link...';
      console.log('Please wait for attribution preparation.');
    }
  });

  // ==========================================
  // 5. READ FACEBOOK COOKIES
  // ==========================================

  function getCookie(name) {
    const prefix = name + '=';
    const item = document.cookie
      .split(';')
      .map(function (part) { return part.trim(); })
      .find(function (part) { return part.indexOf(prefix) === 0; });

    if (!item) return '';

    try {
      return decodeURIComponent(item.substring(prefix.length));
    } catch (err) {
      return item.substring(prefix.length);
    }
  }

  // ==========================================
  // 6. HASH HELPER
  // ==========================================

  async function sha256Hex(value) {
    const normalized = String(value || '').trim().toLowerCase();
    if (!normalized) return '';

    const encoded = new TextEncoder().encode(normalized);
    const digest = await window.crypto.subtle.digest('SHA-256', encoded);

    return Array.from(new Uint8Array(digest))
      .map(function (byte) {
        return ('0' + byte.toString(16)).slice(-2);
      })
      .join('');
  }

  // ==========================================
  // 7. TOKEN GENERATOR
  // ==========================================

  function generateAttributionToken() {
    const bytes = new Uint8Array(16);
    window.crypto.getRandomValues(bytes);
    return Array.from(bytes)
      .map(function (byte) {
        return ('0' + byte.toString(16)).slice(-2);
      })
      .join('');
  }

  // ==========================================
  // 8. CONFIRM ATTRIBUTION RECORD
  // ==========================================

  function confirmAttributionRecord(token) {
    return new Promise(function (resolve, reject) {
      const callbackName = "aiofAttributionCallback_" + token;
      const script = document.createElement("script");
      let finished = false;
      let timeout = null;

      function cleanup() {
        if (finished) return;
        finished = true;
        if (timeout) clearTimeout(timeout);
        delete window[callbackName];
        if (script.parentNode) script.parentNode.removeChild(script);
      }

      window[callbackName] = function (result) {
        cleanup();
        if (result && result.ok === true) {
          resolve(true);
        } else {
          reject(new Error("Apps Script did not confirm the attribution record."));
        }
      };

      script.onerror = function () {
        cleanup();
        reject(new Error("Could not contact the attribution confirmation endpoint."));
      };

      const endpoint = ATTRIBUTION_ENDPOINT +
        "?action=check_attribution" +
        "&token=" + encodeURIComponent(token) +
        "&callback=" + encodeURIComponent(callbackName);

      script.src = endpoint;

      timeout = setTimeout(function () {
        cleanup();
        reject(new Error("Attribution confirmation timed out."));
      }, 15000);

      document.head.appendChild(script);
    });
  }

  // ==========================================
  // 9. PREPARE ATTRIBUTION
  // ==========================================

  async function prepareAttribution() {
    if (
      !window.crypto ||
      !window.crypto.subtle ||
      !window.crypto.getRandomValues
    ) {
      throw new Error('Secure browser encryption is unavailable.');
    }

    const normalizedEmail = selarEmail.trim().toLowerCase();

    if (!normalizedEmail) {
      throw new Error('Selar customer email is missing.');
    }

    const firstName = selarFullName.trim().split(/\s+/)[0] || '';
    const fbp = getCookie('_fbp');

    let fbc = getCookie('_fbc');
    const fbclid = landingFbclid;

    if (!fbc && fbclid) {
      fbc = 'fb.1.' + Date.now() + '.' + fbclid;
    }

    const emailHash = await sha256Hex(normalizedEmail);
    const firstNameHash = firstName ? await sha256Hex(firstName) : '';
    const token = generateAttributionToken();

    const formData = new URLSearchParams();
    formData.set('action', 'save_attribution');
    formData.set('token', token);
    formData.set('emailHash', emailHash);
    formData.set('firstNameHash', firstNameHash);
    formData.set('fbp', fbp);
    formData.set('fbc', fbc);
    formData.set('userAgent', navigator.userAgent);

    // FIX #8: include shared secret if the landing page has one.
    // This is set in config.js as an optional field.
    const sharedSecret = String(CFG.attributionSharedSecret || '').trim();
    if (sharedSecret) {
      formData.set('secret', sharedSecret);
    }

    await fetch(ATTRIBUTION_ENDPOINT, {
      method: 'POST',
      mode: 'no-cors',
      body: formData,
      cache: 'no-store'
    });

    await confirmAttributionRecord(token);

    const startParameter = 'facebook_guide_' + token;
    if (startParameter.length > 64) {
      throw new Error('Telegram attribution parameter is too long.');
    }

    telegramButton.href = TELEGRAM_BASE + token;
    telegramButton.textContent = originalText;
    attributionReady = true;

    console.log('Attribution submission completed.');
  }

  // ==========================================
  // 10. RUN
  // ==========================================

  prepareAttribution().catch(function (err) {
    console.error('Attribution preparation failed:', err);
    telegramButton.href = originalHref;
    telegramButton.textContent = originalText;
    attributionReady = true;
  });

})();